-- Section 78 — Cold War Content Sprint
-- 50 questions: Grade 8 (25) + Grade 9 (25)
-- Bands: B1×12, B2×14, B3×14, B4×10
-- Concepts: superpower rivalry, ideology, arms race, Berlin Wall, Cuba,
--           propaganda, espionage, everyday life, Iron Curtain, end of Cold War
-- Misconceptions targeted throughout. All review_text. is_active=true.

-- ─── GRADE 8 · BAND 1 (6 questions) ─────────────────────────────────────────

-- cw_g8b1_01 — Cold War definition (misconception: not a shooting war)
INSERT INTO public.questions (content, answer_format, answer_type, metadata, type, difficulty, question_type, is_active, learning_objective, target_grade, difficulty_band) VALUES (
  '{"question":"Hvad er \"Den Kolde Krig\"?","options":["En spænding og magtkamp mellem USA og Sovjet uden direkte militær kamp mellem dem","En krig der foregik i kolde klimaer i Sibirien og Arktis","Et navn for 1. Verdenskrig fordi den foregik om vinteren","En krig der aldrig skete — det var kun trusler"],"correct":"En spænding og magtkamp mellem USA og Sovjet uden direkte militær kamp mellem dem","accepted_answers":["En spænding og magtkamp mellem USA og Sovjet uden direkte militær kamp mellem dem"],"review_text":"Den Kolde Krig (1947-1991) var IKKE en krig med skyderi mellem USA og Sovjet. Det var en spænding og magtkamp med atomvåben, propaganda og kapløb om indflydelse. Kold fordi de to supermagter aldrig skød direkte på hinanden."}'::jsonb,
  'mc','short','{"concepts":["kolde krig definition","misconception-skydekrig","supermagter"],"misconception_type":"false_equivalence","cognitive_skill":"recall","difficulty_type":"factual","insight_type":"conceptual_bridge","challenge_role":"reinforcement","domain":"cold_war"}'::jsonb,
  'mc_single',1,'auto',true,'cold_war',8,1
);

-- cw_g8b1_02 — NATO
INSERT INTO public.questions (content, answer_format, answer_type, metadata, type, difficulty, question_type, is_active, learning_objective, target_grade, difficulty_band) VALUES (
  '{"question":"Hvad var NATO under Den Kolde Krig?","options":["En militær alliance ledet af USA til kollektivt forsvar mod Sovjet","Et FN-organ til konfliktmægling mellem supermangterne","Et europæisk handelsforbund uden militær funktion","En videnskabelig organisation til rumforskning"],"correct":"En militær alliance ledet af USA til kollektivt forsvar mod Sovjet","accepted_answers":["En militær alliance ledet af USA til kollektivt forsvar mod Sovjet"],"review_text":"NATO (North Atlantic Treaty Organization) blev oprettet i 1949. Kernen: hvis ét NATO-land angribes, hjælper alle andre. Det var Vestens kollektive militære svar på frygten for Sovjet-invasion af Vesteuropa."}'::jsonb,
  'mc','short','{"concepts":["NATO","militæralliance","kollektivt forsvar"],"misconception_type":"false_equivalence","cognitive_skill":"recall","difficulty_type":"factual","insight_type":"conceptual_bridge","challenge_role":"reinforcement","domain":"cold_war"}'::jsonb,
  'mc_single',1,'auto',true,'cold_war',8,1
);

-- cw_g8b1_03 — Iron Curtain
INSERT INTO public.questions (content, answer_format, answer_type, metadata, type, difficulty, question_type, is_active, learning_objective, target_grade, difficulty_band) VALUES (
  '{"question":"Hvad betød \"Jerntæppet\" i Europa under Den Kolde Krig?","options":["En politisk grænse der delte Europa i en fri vestlig del og en kommunistisk kontrolleret østlig del","En faktisk jernmur der fysisk dækkede hele Europas grænse","Et andet navn for Berlinmuren","En handelsspærring der forhindrede import og eksport"],"correct":"En politisk grænse der delte Europa i en fri vestlig del og en kommunistisk kontrolleret østlig del","accepted_answers":["En politisk grænse der delte Europa i en fri vestlig del og en kommunistisk kontrolleret østlig del"],"review_text":"Jerntæppet var ikke en fysisk mur — det var en politisk og ideologisk grænse. Vest for tæppet: demokrati og kapitalisme. Øst for tæppet: kommunisme under Sovjet-kontrol. Churchill brugte udtrykket i en berømt tale i 1946."}'::jsonb,
  'mc','short','{"concepts":["Jerntæppet","Europa-deling","ideologisk grænse"],"misconception_type":"false_equivalence","cognitive_skill":"recall","difficulty_type":"factual","insight_type":"conceptual_bridge","challenge_role":"reinforcement","domain":"cold_war"}'::jsonb,
  'mc_single',1,'auto',true,'cold_war',8,1
);

-- cw_g8b1_04 — Berlin Wall why built
INSERT INTO public.questions (content, answer_format, answer_type, metadata, type, difficulty, question_type, is_active, learning_objective, target_grade, difficulty_band) VALUES (
  '{"question":"Hvorfor byggede Østtyskland Berlinmuren i 1961?","options":["For at stoppe de millioner der flygtede fra Øst til Vest","For at beskytte Østberlin mod vestlige militæranlæg","Som symbol på kommunismens styrke og stolthed","Fordi FN krævede at Berlin formelt blev delt i to byer"],"correct":"For at stoppe de millioner der flygtede fra Øst til Vest","accepted_answers":["For at stoppe de millioner der flygtede fra Øst til Vest"],"review_text":"Inden muren blev bygget, flygtede millioner af østtyskere til Vesttyskland — heriblandt mange unge og veluddannede. Muren stoppede flugten. Men den lukkede også borgerne inde. Det viser at Øst holdt sine borgere fanget, ikke fri."}'::jsonb,
  'mc','short','{"concepts":["Berlinmuren","flugt","DDR","Vesttyskland"],"misconception_type":"surface_association","cognitive_skill":"recall","difficulty_type":"factual","insight_type":"conceptual_bridge","challenge_role":"reinforcement","domain":"cold_war"}'::jsonb,
  'mc_single',1,'auto',true,'cold_war',8,1
);

-- cw_g8b1_05 — Sputnik
INSERT INTO public.questions (content, answer_format, answer_type, metadata, type, difficulty, question_type, is_active, learning_objective, target_grade, difficulty_band) VALUES (
  '{"question":"Hvad var Sputnik, og hvorfor chokerede det USA?","options":["Den første menneskeskabte satellit — den viste at Sovjet var foran i raketteknologi og potentielt kunne nå USA med atomvåben","Den første atombombe testet af Sovjet i 1957","Et sovjet-spionfly der overvågede amerikanske militærbaser","Den første rumraket der nåede Månen"],"correct":"Den første menneskeskabte satellit — den viste at Sovjet var foran i raketteknologi og potentielt kunne nå USA med atomvåben","accepted_answers":["Den første menneskeskabte satellit — den viste at Sovjet var foran i raketteknologi og potentielt kunne nå USA med atomvåben"],"review_text":"I 1957 sendte Sovjet Sputnik i kredsløb — verdens første satellit. Chokket: hvis Sovjet kan sende en satellit op, kan de sende en atombombe. Det startede rumkapløbet og satte fuld gang i det amerikanske NASA-program."}'::jsonb,
  'mc','short','{"concepts":["Sputnik","rumkapløb","atombombe-trussel","teknologisk chok"],"misconception_type":"false_equivalence","cognitive_skill":"recall","difficulty_type":"factual","insight_type":"conceptual_bridge","challenge_role":"reinforcement","domain":"cold_war"}'::jsonb,
  'mc_single',1,'auto',true,'cold_war',8,1
);

-- cw_g8b1_06 — Arms race basics
INSERT INTO public.questions (content, answer_format, answer_type, metadata, type, difficulty, question_type, is_active, learning_objective, target_grade, difficulty_band) VALUES (
  '{"question":"Hvad var atomkapløbet under Den Kolde Krig?","options":["USA og Sovjet byggede stadig flere atomvåben for at afskrækkeadden anden side fra at angribe","En konkurrence om hvem der testede atomvåben hurtigst","Et kapløb om at sælge atomvåben til allierede lande","En konkurrence om at bygge de største atomkraftværker"],"correct":"USA og Sovjet byggede stadig flere atomvåben for at afskrækkeadden anden side fra at angribe","accepted_answers":["USA og Sovjet byggede stadig flere atomvåben for at afskrækkeadden anden side fra at angribe"],"review_text":"Atomkapløbet betød tusindvis af atomvåben på begge sider — ikke for at bruge dem, men for at skræmme den anden fra at angribe. Jo mere destruktiv du var, desto sikrere var du. En farlig og dyr logik."}'::jsonb,
  'mc','short','{"concepts":["atomkapløb","afskrækkelse","supermagter","våbenopbygning"],"misconception_type":"scope_confusion","cognitive_skill":"recall","difficulty_type":"factual","insight_type":"conceptual_bridge","challenge_role":"reinforcement","domain":"cold_war"}'::jsonb,
  'mc_single',1,'auto',true,'cold_war',8,1
);

-- ─── GRADE 8 · BAND 2 (7 questions) ─────────────────────────────────────────

-- cw_g8b2_01 — Why Cold War started
INSERT INTO public.questions (content, answer_format, answer_type, metadata, type, difficulty, question_type, is_active, learning_objective, target_grade, difficulty_band) VALUES (
  '{"question":"Hvad var den vigtigste årsag til at Den Kolde Krig startede efter 2. Verdenskrig?","options":["USA og Sovjet vandt krigen sammen men delte fundamentalt modsatrettede ideologier — og da fjenden var besejret, forsvandt grundlaget for samarbejdet","USA angreb Sovjet med atomvåben lige efter krigens afslutning","Sovjet invaderede Vesteuropa i 1946 og tvang USA til at reagere militært","FN erklærede krig mellem de to supermagter som en sikkerhedsforanstaltning"],"correct":"USA og Sovjet vandt krigen sammen men delte fundamentalt modsatrettede ideologier — og da fjenden var besejret, forsvandt grundlaget for samarbejdet","accepted_answers":["USA og Sovjet vandt krigen sammen men delte fundamentalt modsatrettede ideologier — og da fjenden var besejret, forsvandt grundlaget for samarbejdet"],"review_text":"USA ville have frie markeder og demokrati. Sovjet ville sprede kommunisme. Da Hitler var besejret, var samarbejdsgrundlaget væk. Mistillid og modsatrettede interesser i Europa eskalerede hurtigt til Den Kolde Krig."}'::jsonb,
  'mc','short','{"concepts":["koldkrig-oprindelse","ideologisk konflikt","efterkrigstid"],"misconception_type":"causal_inversion","cognitive_skill":"comprehension","difficulty_type":"conceptual","insight_type":"reframing","challenge_role":"reinforcement","domain":"cold_war"}'::jsonb,
  'mc_single',2,'auto',true,'cold_war',8,2
);

-- cw_g8b2_02 — Capitalism vs Communism
INSERT INTO public.questions (content, answer_format, answer_type, metadata, type, difficulty, question_type, is_active, learning_objective, target_grade, difficulty_band) VALUES (
  '{"question":"Hvad var den grundlæggende forskel på kapitalisme og kommunisme under Den Kolde Krig?","options":["I kapitalisme ejede private virksomheder produktionen og markedet satte priser; i kommunisme ejede staten alt på fællesskabets vegne","Kapitalisme var kun for rige lande; kommunisme var et system for fattige lande","Kommunisme tillod private virksomheder men med statsregulerede priser","Det var i praksis to navne for det samme system — bare med forskellige politiske symboler"],"correct":"I kapitalisme ejede private virksomheder produktionen og markedet satte priser; i kommunisme ejede staten alt på fællesskabets vegne","accepted_answers":["I kapitalisme ejede private virksomheder produktionen og markedet satte priser; i kommunisme ejede staten alt på fællesskabets vegne"],"review_text":"I kapitalisme (USA): private virksomheder og markedet bestemmer hvad der produceres. I kommunisme (Sovjet): staten ejer og styrer produktionen. To fundamentalt modsatte ideer om økonomi og frihed — det var kernen i Den Kolde Krig."}'::jsonb,
  'mc','short','{"concepts":["kapitalisme","kommunisme","ideologi","økonomi"],"misconception_type":"false_equivalence","cognitive_skill":"comprehension","difficulty_type":"conceptual","insight_type":"reframing","challenge_role":"reinforcement","domain":"cold_war"}'::jsonb,
  'mc_single',2,'auto',true,'cold_war',8,2
);

-- cw_g8b2_03 — Why arms race escalated (MAD logic)
INSERT INTO public.questions (content, answer_format, answer_type, metadata, type, difficulty, question_type, is_active, learning_objective, target_grade, difficulty_band) VALUES (
  '{"question":"Hvorfor blev begge sider ved med at bygge FLERE atomvåben — selv da de allerede havde nok til at ødelægge verden mange gange?","options":["Begge sider frygtede at den anden var teknologisk foran — og ingen turde risikere at stå svagere","Fordi det skabte arbejdspladser og var godt for begge landes økonomi","Fordi FN krævede at begge lande bevarede en minimumsarsenal","Fordi forskere på begge sider konkurrerede om internationale priser"],"correct":"Begge sider frygtede at den anden var teknologisk foran — og ingen turde risikere at stå svagere","accepted_answers":["Begge sider frygtede at den anden var teknologisk foran — og ingen turde risikere at stå svagere"],"review_text":"Logikken hed MAD — Mutually Assured Destruction. Begge parter vidste at et angreb ville betyde selvdestruktion. Men begge frygtede at den anden måske havde en skjult fordel. Det var et kapløb drevet af frygt — ikke faktisk behov."}'::jsonb,
  'mc','short','{"concepts":["MAD","atomkapløb","frygt","eskalation"],"misconception_type":"false_equivalence","cognitive_skill":"comprehension","difficulty_type":"conceptual","insight_type":"reframing","challenge_role":"reinforcement","domain":"cold_war"}'::jsonb,
  'mc_single',2,'auto',true,'cold_war',8,2
);

-- cw_g8b2_04 — Propaganda purpose
INSERT INTO public.questions (content, answer_format, answer_type, metadata, type, difficulty, question_type, is_active, learning_objective, target_grade, difficulty_band) VALUES (
  '{"question":"Hvad var formålet med propaganda under Den Kolde Krig?","options":["At overbevise den egne befolkning om at den anden side var ond og farlig — og at ens eget system var det bedste","At sprede falske militære oplysninger direkte til den fjendtlige hær","At rekruttere spioner i det andet lands ambassader","At informere neutrale lande neutralt om konflikten"],"correct":"At overbevise den egne befolkning om at den anden side var ond og farlig — og at ens eget system var det bedste","accepted_answers":["At overbevise den egne befolkning om at den anden side var ond og farlig — og at ens eget system var det bedste"],"review_text":"Begge sider brugte propaganda. Amerikanske skolebørn øvede atombombe-drills. Sovjet-borgere lærte at USA var et land styret af grådige kapitalister. Propaganda handlede om at kontrollere hvad din EGEN befolkning troede — ikke hvad fjenden troede."}'::jsonb,
  'mc','short','{"concepts":["propaganda","befolkningskontrol","ideologi"],"misconception_type":"scope_confusion","cognitive_skill":"comprehension","difficulty_type":"conceptual","insight_type":"reframing","challenge_role":"reinforcement","domain":"cold_war"}'::jsonb,
  'mc_single',2,'auto',true,'cold_war',8,2
);

-- cw_g8b2_05 — Space Race significance
INSERT INTO public.questions (content, answer_format, answer_type, metadata, type, difficulty, question_type, is_active, learning_objective, target_grade, difficulty_band) VALUES (
  '{"question":"Hvad betød rumkapløbet for Den Kolde Krig udover selve rumforskningen?","options":["Det var en ideologisk prestigekamp: den side der vandt i rummet beviste at dens system — kapitalisme eller kommunisme — var overlegen","Det var en aftale om at konkurrere fredeligt i rummet i stedet for med atomvåben","Det handlede primært om at finde naturressourcer på Månen og Mars","Rumkapløbet var adskilt fra Den Kolde Krig og fulgte sine egne regler"],"correct":"Det var en ideologisk prestigekamp: den side der vandt i rummet beviste at dens system — kapitalisme eller kommunisme — var overlegen","accepted_answers":["Det var en ideologisk prestigekamp: den side der vandt i rummet beviste at dens system — kapitalisme eller kommunisme — var overlegen"],"review_text":"Rummet var ikke blot videnskab — det var ideologisk scenen. Sovjet i rummet: kommunisme virker. USA på Månen: kapitalisme og frihed kan opnå det umulige. Hvert nyt rumrekord var gevinst i en global PR-kamp om hvem der havde det bedste system."}'::jsonb,
  'mc','short','{"concepts":["rumkapløb","ideologisk prestige","Sputnik","Månen"],"misconception_type":"scope_confusion","cognitive_skill":"comprehension","difficulty_type":"conceptual","insight_type":"reframing","challenge_role":"reinforcement","domain":"cold_war"}'::jsonb,
  'mc_single',2,'auto',true,'cold_war',8,2
);

-- cw_g8b2_06 — Iron Curtain everyday people
INSERT INTO public.questions (content, answer_format, answer_type, metadata, type, difficulty, question_type, is_active, learning_objective, target_grade, difficulty_band) VALUES (
  '{"question":"Hvad betød Jerntæppet konkret for almindelige borgere i Østeuropa?","options":["De kunne ikke frit rejse til Vesteuropa og adgang til vestlig information og medier var kraftigt begrænset","Det betød kun en politisk grænse — folk på begge sider rejste frit og kommunikerede uhindret","Vesteuropæere måtte ikke besøge Østeuropa men østeuropæere rejste frit vestpå","Det påvirkede primært politikere og militær — ikke normalbefolkningens hverdagsliv"],"correct":"De kunne ikke frit rejse til Vesteuropa og adgang til vestlig information og medier var kraftigt begrænset","accepted_answers":["De kunne ikke frit rejse til Vesteuropa og adgang til vestlig information og medier var kraftigt begrænset"],"review_text":"Jerntæppet var meget konkret i folks liv. Østeuropæere måtte ikke rejse frit til vest. Vestlige aviser og radio var forbudte eller jammede. Breve og telefonopkald til vestlige lande var overvågede. Frihed var en politisk beslutning — ikke en menneskeret."}'::jsonb,
  'mc','short','{"concepts":["Jerntæppet","hverdagsliv","rejsefrihed","censur","misconception-folk-upåvirkede"],"misconception_type":"overgeneralization","cognitive_skill":"comprehension","difficulty_type":"conceptual","insight_type":"reframing","challenge_role":"reinforcement","domain":"cold_war"}'::jsonb,
  'mc_single',2,'auto',true,'cold_war',8,2
);

-- cw_g8b2_07 — Berlin Wall impact on families
INSERT INTO public.questions (content, answer_format, answer_type, metadata, type, difficulty, question_type, is_active, learning_objective, target_grade, difficulty_band) VALUES (
  '{"question":"Hvad var den umiddelbare menneskelige konsekvens af Berlinmurens opførelse natten den 13. august 1961?","options":["Familier der boede på hver sin side af muren var pludselig afskåret fra hinanden","Muren skabte ti tusinder af nye arbejdspladser i byggeri og vagt","Muren gjorde Berlin til en sikrere by for alle borgere på begge sider","Borgerne på begge sider modtog kompensation fra regeringerne"],"correct":"Familier der boede på hver sin side af muren var pludselig afskåret fra hinanden","accepted_answers":["Familier der boede på hver sin side af muren var pludselig afskåret fra hinanden"],"review_text":"Berlinmuren tog ingen hensyn til familier. Natten den blev bygget var folk pludselig adskilt. Søskende, forældre og børn på hver sin side. Mange så ikke hinanden igen i årtier. Muren var politisk logik der ødelagde virkelige menneskers liv."}'::jsonb,
  'mc','short','{"concepts":["Berlinmuren","familiepåvirkning","menneskelig konsekvens"],"misconception_type":"scope_confusion","cognitive_skill":"comprehension","difficulty_type":"conceptual","insight_type":"reframing","challenge_role":"reinforcement","domain":"cold_war"}'::jsonb,
  'mc_single',2,'auto',true,'cold_war',8,2
);

-- ─── GRADE 8 · BAND 3 (7 questions) ─────────────────────────────────────────

-- cw_g8b3_01 — Communism ≠ dictatorship (misconception)
INSERT INTO public.questions (content, answer_format, answer_type, metadata, type, difficulty, question_type, is_active, learning_objective, target_grade, difficulty_band) VALUES (
  '{"question":"Er kommunisme og diktatur det samme?","options":["Nej — kommunisme er en ideologi om fælles ejerskab; diktatur er en styreform. Sovjet kombinerede dem i praksis — men de er ikke det samme per definition","Ja — alle kommunistiske lande var altid og nødvendigvis diktaturer","Ja — Marx og Lenin designede fra starten kommunisme som et enpartidiktatur","Nej — Sovjet var ikke et diktatur men blot et autoritært demokrati med ét parti"],"correct":"Nej — kommunisme er en ideologi om fælles ejerskab; diktatur er en styreform. Sovjet kombinerede dem i praksis — men de er ikke det samme per definition","accepted_answers":["Nej — kommunisme er en ideologi om fælles ejerskab; diktatur er en styreform. Sovjet kombinerede dem i praksis — men de er ikke det samme per definition"],"review_text":"Marx forestillede sig kommunisme som befrielse af arbejderne fra kapitalistisk udbytning — ikke diktatur. Lenin og Stalin formede det til enpartistyre med hemmelig politi. Teorien og praksis kan divergere dramatisk. Det er en af historiens vigtigste lektioner."}'::jsonb,
  'mc','short','{"concepts":["kommunisme","diktatur","ideologi","misconception-kommunisme=diktatur"],"misconception_type":"false_equivalence","cognitive_skill":"analysis","difficulty_type":"analytical","insight_type":"reframing","challenge_role":"challenge","domain":"cold_war"}'::jsonb,
  'mc_single',3,'auto',true,'cold_war',8,3
);

-- cw_g8b3_02 — Cuban Missile Crisis global threat (misconception: not just Cuba)
INSERT INTO public.questions (content, answer_format, answer_type, metadata, type, difficulty, question_type, is_active, learning_objective, target_grade, difficulty_band) VALUES (
  '{"question":"Hvad var grunden til at Cuba-krisen i 1962 truede HELE verden — og ikke kun Cuba?","options":["Sovjet-raketterne i Cuba kunne ramme de fleste store amerikanske byer på 14 minutter — og et angreb på Cuba kunne udløse atomkrig","Krisens geografiske centrum var i Atlanterhavet og truede al international skibstrafik","Cuba selv truede med at erklære krig mod alle NATO-lande","FN var på nippet til at kollapse under presset fra begge supermagter"],"correct":"Sovjet-raketterne i Cuba kunne ramme de fleste store amerikanske byer på 14 minutter — og et angreb på Cuba kunne udløse atomkrig","accepted_answers":["Sovjet-raketterne i Cuba kunne ramme de fleste store amerikanske byer på 14 minutter — og et angreb på Cuba kunne udløse atomkrig"],"review_text":"Fra Cuba til Washington D.C. er der kun 14 minutters flyvtid for en raket. Sovjet-raketter i Cuba var ikke en trussel mod Cuba — de var rettet mod USA. Et angreb på Cuba ville sandsynligvis have udløst atomkrig. Hele verden var 13 dage fra mulig atomkrig."}'::jsonb,
  'mc','short','{"concepts":["Cuba-krisen","global trussel","misconception-kun-Cuba","atomkrig"],"misconception_type":"scope_confusion","cognitive_skill":"analysis","difficulty_type":"analytical","insight_type":"perspective_shift","challenge_role":"challenge","domain":"cold_war"}'::jsonb,
  'mc_single',3,'auto',true,'cold_war',8,3
);

-- cw_g8b3_03 — Proxy wars
INSERT INTO public.questions (content, answer_format, answer_type, metadata, type, difficulty, question_type, is_active, learning_objective, target_grade, difficulty_band) VALUES (
  '{"question":"Hvad var en \"proxy-krig\", og hvordan afspejler Koreakrigen og Vietnamkrigen dette?","options":["Krige hvor USA og Sovjet støttede modsatte sider uden selv at kæmpe mod hinanden direkte — og derved dræbte millioner uden formel krig","Krige styret med fjernkontrollerede våben og tidlige droner","Hemmelige krige som befolkningerne i USA og Sovjet aldrig kendte til","Krige der foregik i neutrale lande for at undgå at inddrage supermagternes egne territorier"],"correct":"Krige hvor USA og Sovjet støttede modsatte sider uden selv at kæmpe mod hinanden direkte — og derved dræbte millioner uden formel krig","accepted_answers":["Krige hvor USA og Sovjet støttede modsatte sider uden selv at kæmpe mod hinanden direkte — og derved dræbte millioner uden formel krig"],"review_text":"USA støttede Sydkorea og Sydvietnam. Sovjet støttede Nordkorea og Nordvietnam. Supermangterne kæmpede via allierede — ikke direkte. Den Kolde Krig var kold for supermagterne; varm og dødelig for koreanere og vietnamesere. Millioner døde i disse proxy-konflikter."}'::jsonb,
  'mc','short','{"concepts":["proxy-krig","Koreakrig","Vietnamkrig","indirekte konflikt"],"misconception_type":"overgeneralization","cognitive_skill":"analysis","difficulty_type":"analytical","insight_type":"reframing","challenge_role":"challenge","domain":"cold_war"}'::jsonb,
  'mc_single',3,'auto',true,'cold_war',8,3
);

-- cw_g8b3_04 — Everyday life misconception
INSERT INTO public.questions (content, answer_format, answer_type, metadata, type, difficulty, question_type, is_active, learning_objective, target_grade, difficulty_band) VALUES (
  '{"question":"Hvad er forkert ved påstanden at Den Kolde Krig kun påvirkede politikere og militæret?","options":["Ordinære borgere levede med atombombe-drills, propaganda, rejseforbud og frygt for atomkrig som reelle hverdagselementer","Påstanden er korrekt — al beslutningstagning skete bag lukkede politiske døre","Kun borgere tæt på militærbaser var reelt påvirkede","Kun borgere i Sovjet var påvirkede — vestlige borgere levede normalt"],"correct":"Ordinære borgere levede med atombombe-drills, propaganda, rejseforbud og frygt for atomkrig som reelle hverdagselementer","accepted_answers":["Ordinære borgere levede med atombombe-drills, propaganda, rejseforbud og frygt for atomkrig som reelle hverdagselementer"],"review_text":"Amerikanske skolebørn øvede duck-and-cover mod atombombe. Østeuropæere levede med overvågning og rejseforbud. Den Kolde Krig formede film, musik, sport og skolelæreplaner. Ingen blev skånet fra dens påvirkning — hverken i øst eller vest."}'::jsonb,
  'mc','short','{"concepts":["hverdagsliv","misconception-folk-upåvirkede","propaganda","frygt","duck-and-cover"],"misconception_type":"overgeneralization","cognitive_skill":"analysis","difficulty_type":"analytical","insight_type":"perspective_shift","challenge_role":"challenge","domain":"cold_war"}'::jsonb,
  'mc_single',3,'auto',true,'cold_war',8,3
);

-- cw_g8b3_05 — MAD paradox
INSERT INTO public.questions (content, answer_format, answer_type, metadata, type, difficulty, question_type, is_active, learning_objective, target_grade, difficulty_band) VALUES (
  '{"question":"Hvad var det paradoksale ved strategien om Gensidig Sikret Ødelæggelse (MAD)?","options":["Jo flere destruktive atomvåben du ejede, desto mere stabil var situationen — fordi ingen turde bruge dem","Jo færre atomvåben du havde, desto sikrere var du — og dermed var kapløbet irrationelt","MAD betød at begge sider var enige om at dele deres atomvåben ligeligt som afskrækkelse","Logikken betød at atomvåben kun ville rettes mod militære mål — aldrig mod civile"],"correct":"Jo flere destruktive atomvåben du ejede, desto mere stabil var situationen — fordi ingen turde bruge dem","accepted_answers":["Jo flere destruktive atomvåben du ejede, desto mere stabil var situationen — fordi ingen turde bruge dem"],"review_text":"MAD er et paradoks: mere destruktive våben skabte paradoksal stabilitet. Begge parter vidste at et angreb ville betyde total ødelæggelse af begge. Ingen turde angribe. Men denne stabilitet krævede konstant frygt og enorme udgifter til våben der aldrig måtte bruges."}'::jsonb,
  'mc','short','{"concepts":["MAD","afskrækkelse","paradoks","nuklear stabilitet"],"misconception_type":"causal_inversion","cognitive_skill":"analysis","difficulty_type":"analytical","insight_type":"reframing","challenge_role":"challenge","domain":"cold_war"}'::jsonb,
  'mc_single',3,'auto',true,'cold_war',8,3
);

-- cw_g8b3_06 — Espionage not just weapons
INSERT INTO public.questions (content, answer_format, answer_type, metadata, type, difficulty, question_type, is_active, learning_objective, target_grade, difficulty_band) VALUES (
  '{"question":"Hvad viser den massive brug af spionage under Den Kolde Krig om konfliktens natur?","options":["At konflikten ikke kun handlede om våben — information, teknologiske hemmeligheder og politiske planer var ligeså vigtige magtfaktorer","At begge sider primært spionerede mod neutrale lande for at rekruttere allierede","At spionage erstattede al militær aktivitet under Den Kolde Krig","At CIA og KGB i virkeligheden samarbejdede hemmelig om at fordele spionopgaverne"],"correct":"At konflikten ikke kun handlede om våben — information, teknologiske hemmeligheder og politiske planer var ligeså vigtige magtfaktorer","accepted_answers":["At konflikten ikke kun handlede om våben — information, teknologiske hemmeligheder og politiske planer var ligeså vigtige magtfaktorer"],"review_text":"CIA og KGB brugte enorme ressourcer på spioner, dobbelt-agenter og aflytning. De jagede atomhemmeligheder, militære planer og politisk information om hinandens lederskab. Den Kolde Krig var en informationskrig i ligeså høj grad som en våbenkrig."}'::jsonb,
  'mc','short','{"concepts":["spionage","CIA","KGB","informationskrig","misconception-kun-våben"],"misconception_type":"scope_confusion","cognitive_skill":"analysis","difficulty_type":"analytical","insight_type":"reframing","challenge_role":"challenge","domain":"cold_war"}'::jsonb,
  'mc_single',3,'auto',true,'cold_war',8,3
);

-- cw_g8b3_07 — Germany division consequences
INSERT INTO public.questions (content, answer_format, answer_type, metadata, type, difficulty, question_type, is_active, learning_objective, target_grade, difficulty_band) VALUES (
  '{"question":"Hvad betød delingen af Tyskland i Øst og Vest for det tyske folk?","options":["En nation med fælles sprog og kultur i et årtusind blev politisk splittet — to generationer voksede op med radikalt forskellige politiske virkeligheder","Befolkningerne i Øst og Vest udviklede sig til to helt adskilte folk med egne sprog og identiteter","Delingen betød primært militære konsekvenser — civile liv var i store træk uforandrede","Østtyskerne fik dårligere kår men var grundlæggende tilfredse med det kommunistiske system"],"correct":"En nation med fælles sprog og kultur i et årtusind blev politisk splittet — to generationer voksede op med radikalt forskellige politiske virkeligheder","accepted_answers":["En nation med fælles sprog og kultur i et årtusind blev politisk splittet — to generationer voksede op med radikalt forskellige politiske virkeligheder"],"review_text":"I vest: demokrati, velstand og rejsefrihed. I øst: enpartidiktatur, planøkonomi og Stasi-overvågning. To generationer af tyskere voksede op i vidt forskellige verdener. Da genforeningen kom i 1990, mødte to fundamentalt different befolkninger hinanden."}'::jsonb,
  'mc','short','{"concepts":["Tysklands deling","DDR","Vesttyskland","national identitet","genforening"],"misconception_type":"scope_confusion","cognitive_skill":"analysis","difficulty_type":"analytical","insight_type":"perspective_shift","challenge_role":"challenge","domain":"cold_war"}'::jsonb,
  'mc_single',3,'auto',true,'cold_war',8,3
);

