-- cw_g8b4_01 — USA perspective on communism as threat
INSERT INTO public.questions (content, answer_format, answer_type, metadata, type, difficulty, question_type, is_active, learning_objective, target_grade, difficulty_band) VALUES (
  '{"question":"Hvorfor opfattede mange amerikanere kommunisme som en eksistentiel trussel under Den Kolde Krig?","options":["Kommunisme truede privat ejendomsret og demokratiet som USA byggede sin identitet på — og Sovjet forsøgte aktivt at sprede det globalt","Fordi kommunistiske lande altid angreb NATO-lande militært","Fordi USA-borgere personligt mistede ejendom på grund af Sovjet-aktiviteter","Fordi FN erklærede kommunisme som en ulovlig international ideologi"],"correct":"Kommunisme truede privat ejendomsret og demokratiet som USA byggede sin identitet på — og Sovjet forsøgte aktivt at sprede det globalt","accepted_answers":["Kommunisme truede privat ejendomsret og demokratiet som USA byggede sin identitet på — og Sovjet forsøgte aktivt at sprede det globalt"],"review_text":"For mange amerikanere truede kommunisme selve fundamentet: privat ejendom, frie markeder og demokrati. Sovjet spredte aktivt kommunisme i Afrika, Asien og Latinamerika. USA så det som en trussel mod hele den verden-orden der gav USA sin magt og identitet."}'::jsonb,
  'mc','short','{"concepts":["USA-perspektiv","kommunismefrygt","ideologi","perspektiv"],"misconception_type":"causal_inversion","cognitive_skill":"evaluation","difficulty_type":"applied","insight_type":"perspective_shift","challenge_role":"deep_challenge","domain":"cold_war"}'::jsonb,
  'mc_single',4,'auto',true,'cold_war',8,4
);

-- cw_g8b4_02 — Soviet perspective on USA
INSERT INTO public.questions (content, answer_format, answer_type, metadata, type, difficulty, question_type, is_active, learning_objective, target_grade, difficulty_band) VALUES (
  '{"question":"Hvordan kunne Sovjet retfærdiggøre sin politik under Den Kolde Krig fra eget perspektiv?","options":["Sovjet var omringet af USA-militærbaser og NATO-alliancer og så sig som en nation der forsvarede sig mod vestlig omringning og kapitalistisk aggression","Sovjet ønskede aktivt at starte atomkrig og ventede bare på det rette tidspunkt","Sovjet-lederskabet var rent paranoid og handlede uden faktuelle grunde til bekymring","Sovjet opfattede USA som en samarbejdspartner der trak for hurtigt ud af Europa"],"correct":"Sovjet var omringet af USA-militærbaser og NATO-alliancer og så sig som en nation der forsvarede sig mod vestlig omringning og kapitalistisk aggression","accepted_answers":["Sovjet var omringet af USA-militærbaser og NATO-alliancer og så sig som en nation der forsvarede sig mod vestlig omringning og kapitalistisk aggression"],"review_text":"Fra Sovjet-perspektiv: USA havde atomvåben og militærbaser i alle nabolande. NATO omringede dem strategisk. USA propaganderede aktivt for at underminere kommunistiske regimer. At forstå modpartens perspektiv er ikke at godkende det — det er at forstå historien fuldt ud."}'::jsonb,
  'mc','short','{"concepts":["Sovjet-perspektiv","omringning","USA-aggression","misconception-Sovjet-altid-forkert"],"misconception_type":"causal_inversion","cognitive_skill":"evaluation","difficulty_type":"applied","insight_type":"perspective_shift","challenge_role":"deep_challenge","domain":"cold_war"}'::jsonb,
  'mc_single',4,'auto',true,'cold_war',8,4
);

-- cw_g8b4_03 — Leaders vs ordinary people experience
INSERT INTO public.questions (content, answer_format, answer_type, metadata, type, difficulty, question_type, is_active, learning_objective, target_grade, difficulty_band) VALUES (
  '{"question":"Hvad var den afgørende forskel på hvordan politiske ledere og ordinære borgere oplevede Den Kolde Krig?","options":["Ledere tog beslutningerne bag lukkede fortrolige døre; borgere bar konsekvenserne i hverdagen — atombombe-angst, propaganda og begrænsede friheder","Borgerne var bedre informerede end lederne om den faktiske militære situation","Borgerne i øst og vest oplevede situationen identisk — kun regeringerne var uenige","Politikerne bar den tungeste psykologiske byrde; borgerne var stort set upåvirkede"],"correct":"Ledere tog beslutningerne bag lukkede fortrolige døre; borgere bar konsekvenserne i hverdagen — atombombe-angst, propaganda og begrænsede friheder","accepted_answers":["Ledere tog beslutningerne bag lukkede fortrolige døre; borgere bar konsekvenserne i hverdagen — atombombe-angst, propaganda og begrænsede friheder"],"review_text":"Kennedy og Khrushchev forhandlede bag lukkede døre med fortrolige rapporter. Borgere levede med drills, propagandafilm og rejseforbud som hverdagsrealiteter. Beslutningerne lå hos lederne — konsekvenserne ramte alle."}'::jsonb,
  'mc','short','{"concepts":["ledere","borgere","hverdagsliv","magtasymmetri","perspektiv"],"misconception_type":"scope_confusion","cognitive_skill":"evaluation","difficulty_type":"applied","insight_type":"perspective_shift","challenge_role":"deep_challenge","domain":"cold_war"}'::jsonb,
  'mc_single',4,'auto',true,'cold_war',8,4
);

-- cw_g8b4_04 — Both sides used propaganda (symmetry)
INSERT INTO public.questions (content, answer_format, answer_type, metadata, type, difficulty, question_type, is_active, learning_objective, target_grade, difficulty_band) VALUES (
  '{"question":"Hvad var den dybere årsag til at BEGGE sider — USA og Sovjet — brugte massiv propaganda mod deres egne borgere?","options":["Begge magter havde brug for befolkningens støtte til ofringer — enorme militærudgifter og frihedsbegrænsninger — og propaganda sikrede denne opbakning","Kun Sovjet brugte propaganda; USA informerede sine borgere faktabaseret og objektivt","Propaganda var et FN-krav til begge supermagter som betingelse for at sidde i Sikkerhedsrådet","Begge sider brugte propaganda fordi det var billigere end faktisk militæropbygning"],"correct":"Begge magter havde brug for befolkningens støtte til ofringer — enorme militærudgifter og frihedsbegrænsninger — og propaganda sikrede denne opbakning","accepted_answers":["Begge magter havde brug for befolkningens støtte til ofringer — enorme militærudgifter og frihedsbegrænsninger — og propaganda sikrede denne opbakning"],"review_text":"Propaganda er ikke kun et diktatur-fænomen. USA skabte Hollywood-film og skolekampagner der fremstillede Sovjet som ondsindede tyranner. Begge sider havde brug for at befolkningerne accepterede enorme militærudgifter og frihedsbegrænsninger. Propaganda var et styringsværktøj for begge."}'::jsonb,
  'mc','short','{"concepts":["propaganda","begge sider","befolkningskontrol","misconception-USA-altid-rigtig"],"misconception_type":"false_equivalence","cognitive_skill":"evaluation","difficulty_type":"applied","insight_type":"perspective_shift","challenge_role":"deep_challenge","domain":"cold_war"}'::jsonb,
  'mc_single',4,'auto',true,'cold_war',8,4
);

-- cw_g8b4_05 — Berlin Wall: state vs citizens perspectives
INSERT INTO public.questions (content, answer_format, answer_type, metadata, type, difficulty, question_type, is_active, learning_objective, target_grade, difficulty_band) VALUES (
  '{"question":"Hvad afslører forskellene i statens og borgernes oplevelse af Berlinmuren?","options":["Staten kaldte den officielt en antifascistisk beskyttelsesvold; borgerne oplevede den som et fængselshegn — over 140 døde i forsøg på at krydse den","Begge — stat og borgere — var enige om at muren var en nødvendig sikkerhedsforanstaltning","Borgerne var stolte af muren som et symbol på østtysk styrke og selvstændighed","Staten sagde den var midlertidig; borgerne vidste det ikke ville vare"],"correct":"Staten kaldte den officielt en antifascistisk beskyttelsesvold; borgerne oplevede den som et fængselshegn — over 140 døde i forsøg på at krydse den","accepted_answers":["Staten kaldte den officielt en antifascistisk beskyttelsesvold; borgerne oplevede den som et fængselshegn — over 140 døde i forsøg på at krydse den"],"review_text":"Den østtyske stat kaldte muren officielt Antifaschistischer Schutzwall — beskyttelse mod vestlig fascisme. Borgerne der risikerede livet for at krydse den, oplevede et fængsel. Over 140 mennesker døde i flugtforsøg. Ord og virkelighed var vidt forskellig."}'::jsonb,
  'mc','short','{"concepts":["Berlinmuren","statspropaganda","borgerlige konsekvenser","perspektiv"],"misconception_type":"causal_inversion","cognitive_skill":"evaluation","difficulty_type":"applied","insight_type":"perspective_shift","challenge_role":"deep_challenge","domain":"cold_war"}'::jsonb,
  'mc_single',4,'auto',true,'cold_war',8,4
);

