-- cw_g9b1_01 — Cuban Missile Crisis basics
INSERT INTO public.questions (content, answer_format, answer_type, metadata, type, difficulty, question_type, is_active, learning_objective, target_grade, difficulty_band) VALUES (
  '{"question":"Hvad skete under Cuba-krisen i oktober 1962?","options":["USA opdagede Sovjet-atomraketter i Cuba — 13 dage på kanten af atomkrig endte da Khrushchev trak raketterne tilbage","Cuba forsøgte med Sovjet-støtte at invadere Florida","USA satte egne atomraketter på Cuba som svar på en Sovjet-provokation","FN afholdt en nødkonference på Cuba der løste krisen hurtigt"],"correct":"USA opdagede Sovjet-atomraketter i Cuba — 13 dage på kanten af atomkrig endte da Khrushchev trak raketterne tilbage","accepted_answers":["USA opdagede Sovjet-atomraketter i Cuba — 13 dage på kanten af atomkrig endte da Khrushchev trak raketterne tilbage"],"review_text":"Et amerikansk spionfly opdagede i oktober 1962 Sovjet-raketter i Cuba. USA blokerede Cuba. 13 dage stod verden på kanten af atomkrig. Til sidst trak Khrushchev raketterne tilbage, Kennedy lovede ikke at invadere Cuba. Det tætteste verden kom på atomkrig under Den Kolde Krig."}'::jsonb,
  'mc','short','{"concepts":["Cuba-krisen","1962","Khrushchev","Kennedy","atomkrig"],"misconception_type":"false_equivalence","cognitive_skill":"recall","difficulty_type":"factual","insight_type":"conceptual_bridge","challenge_role":"reinforcement","domain":"cold_war"}'::jsonb,
  'mc_single',1,'auto',true,'cold_war',9,1
);

-- cw_g9b1_02 — Warsaw Pact
INSERT INTO public.questions (content, answer_format, answer_type, metadata, type, difficulty, question_type, is_active, learning_objective, target_grade, difficulty_band) VALUES (
  '{"question":"Hvad var Warszawapagten?","options":["Sovjet-ledede militæralliance for Østeuropas kommunistiske lande — modstykket til NATO","En fredsaftale underskrevet af alle europæiske lande i 1955","En handelsaftale der bandt Østeuropa til Sovjet-markedet","Et FN-organ til overvågning af den europæiske grænse"],"correct":"Sovjet-ledede militæralliance for Østeuropas kommunistiske lande — modstykket til NATO","accepted_answers":["Sovjet-ledede militæralliance for Østeuropas kommunistiske lande — modstykket til NATO"],"review_text":"Warszawapagten (1955) var Sovjet-blokens svar på NATO. Lande som Polen, Tjekkoslovakiet og Østtyskland var militært forpligtet til Sovjet. Ligesom NATO sikrede kollektivt forsvar — men denne gang rettet mod Vesten."}'::jsonb,
  'mc','short','{"concepts":["Warszawapagten","Sovjet-blok","militæralliance","NATO"],"misconception_type":"false_equivalence","cognitive_skill":"recall","difficulty_type":"factual","insight_type":"conceptual_bridge","challenge_role":"reinforcement","domain":"cold_war"}'::jsonb,
  'mc_single',1,'auto',true,'cold_war',9,1
);

-- cw_g9b1_03 — Gorbachev reforms
INSERT INTO public.questions (content, answer_format, answer_type, metadata, type, difficulty, question_type, is_active, learning_objective, target_grade, difficulty_band) VALUES (
  '{"question":"Hvad betød Gorbatjovs reformer glasnost og perestrojka?","options":["Glasnost = åbenhed i information; perestrojka = omstrukturering af økonomien — reformer der utilsigtet accelererede Sovjet-systemets sammenbrud","Glasnost = mere censur; perestrojka = nationalisering af private virksomheder","Militær opbygning og lukning af grænser for at beskytte Sovjet mod vestlig indflydelse","Det var propaganda-begreber uden reel politisk indhold bag sig"],"correct":"Glasnost = åbenhed i information; perestrojka = omstrukturering af økonomien — reformer der utilsigtet accelererede Sovjet-systemets sammenbrud","accepted_answers":["Glasnost = åbenhed i information; perestrojka = omstrukturering af økonomien — reformer der utilsigtet accelererede Sovjet-systemets sammenbrud"],"review_text":"Gorbatjov ville reformere Sovjet — ikke ødelægge det. Glasnost tillod offentlig kritik. Perestrojka forsøgte at effektivisere den stagnerede økonomi. Men reformerne løsnede kontrollen og åbnede for folkeopstande. Resultatet: Sovjet kollapsede i 1991."}'::jsonb,
  'mc','short','{"concepts":["Gorbatjov","glasnost","perestrojka","Sovjet-sammenbrud"],"misconception_type":"causal_inversion","cognitive_skill":"recall","difficulty_type":"factual","insight_type":"conceptual_bridge","challenge_role":"reinforcement","domain":"cold_war"}'::jsonb,
  'mc_single',1,'auto',true,'cold_war',9,1
);

-- cw_g9b1_04 — End of Cold War when
INSERT INTO public.questions (content, answer_format, answer_type, metadata, type, difficulty, question_type, is_active, learning_objective, target_grade, difficulty_band) VALUES (
  '{"question":"Hvornår sluttede Den Kolde Krig og hvad var de to vigtigste tegn?","options":["1989-1991 — Berlinmurens fald i november 1989 og Sovjet-Unionens opløsning i december 1991","1963 da begge sider underskrev en fredsaftale efter Cuba-krisen","1975 da USA trak sig ud af Vietnam og opgav sin militære overlegenhed","1980 da Reagan vandt præsidentvalget med anti-Sovjet program"],"correct":"1989-1991 — Berlinmurens fald i november 1989 og Sovjet-Unionens opløsning i december 1991","accepted_answers":["1989-1991 — Berlinmurens fald i november 1989 og Sovjet-Unionens opløsning i december 1991"],"review_text":"Den Kolde Krig sluttede gradvist 1989-1991. Berlinmurens fald 9. november 1989 var det mest dramatiske tegn. To år senere opløstes Sovjet-Unionen i 15 selvstændige stater. Det var ikke et punktum — det var en langsom opløsning."}'::jsonb,
  'mc','short','{"concepts":["Kolde Krig afslutning","Berlinmur","Sovjet-opløsning","misconception-øjeblikkelig slutning"],"misconception_type":"temporal_confusion","cognitive_skill":"recall","difficulty_type":"factual","insight_type":"conceptual_bridge","challenge_role":"reinforcement","domain":"cold_war"}'::jsonb,
  'mc_single',1,'auto',true,'cold_war',9,1
);

-- cw_g9b1_05 — MAD concept
INSERT INTO public.questions (content, answer_format, answer_type, metadata, type, difficulty, question_type, is_active, learning_objective, target_grade, difficulty_band) VALUES (
  '{"question":"Hvad stod MAD for under Den Kolde Krig?","options":["Mutually Assured Destruction — gensidig sikret ødelæggelse: hvis én side angriber, ødelægges begge","Military Advancement Division — den afdeling i Pentagon der styrede atomvåbnene","Multilateral Arms Disarmament — en FN-aftale om gradvis atomnedrustning","Moscow-America Dialogue — den direkte telefonlinje mellem de to supermagter"],"correct":"Mutually Assured Destruction — gensidig sikret ødelæggelse: hvis én side angriber, ødelægges begge","accepted_answers":["Mutually Assured Destruction — gensidig sikret ødelæggelse: hvis én side angriber, ødelægges begge"],"review_text":"MAD var den strategiske logik der afskrækkede begge sider fra at angribe. Hvis USA angreb med atomvåben, ville Sovjet svare. Begge ødelægges. Ingen turde starte. En form for stabilitet baseret på frygt for fuldstændig gensidig udslettelse."}'::jsonb,
  'mc','short','{"concepts":["MAD","atomafskrækkelse","nuklear strategi"],"misconception_type":"false_equivalence","cognitive_skill":"recall","difficulty_type":"factual","insight_type":"conceptual_bridge","challenge_role":"reinforcement","domain":"cold_war"}'::jsonb,
  'mc_single',1,'auto',true,'cold_war',9,1
);

-- cw_g9b1_06 — Checkpoint Charlie
INSERT INTO public.questions (content, answer_format, answer_type, metadata, type, difficulty, question_type, is_active, learning_objective, target_grade, difficulty_band) VALUES (
  '{"question":"Hvad var Checkpoint Charlie?","options":["Den mest kendte grænseovergang i Berlinmuren — det eneste officielle sted vestlige allierede og diplomater måtte passere til Østberlin","En berømt dobbelt-agent der arbejdede for begge sider under Den Kolde Krig","En NATO-kommandopost på grænsen til Sovjet-kontrolleret territorium","Et kodenavn for USA-spionfly der overvågede Østeuropa"],"correct":"Den mest kendte grænseovergang i Berlinmuren — det eneste officielle sted vestlige allierede og diplomater måtte passere til Østberlin","accepted_answers":["Den mest kendte grænseovergang i Berlinmuren — det eneste officielle sted vestlige allierede og diplomater måtte passere til Østberlin"],"review_text":"Checkpoint Charlie var et symbol på det delte Berlin. Her mødte øst og vest hinanden ansigt til ansigt — soldater fra supermagterne foran hinanden. Det eneste officielle krydsningspunkt for vestlige diplomater og allierede. I dag er det et museum i Berlin."}'::jsonb,
  'mc','short','{"concepts":["Checkpoint Charlie","Berlinmuren","Berlin","grænseovergang"],"misconception_type":"false_equivalence","cognitive_skill":"recall","difficulty_type":"factual","insight_type":"conceptual_bridge","challenge_role":"reinforcement","domain":"cold_war"}'::jsonb,
  'mc_single',1,'auto',true,'cold_war',9,1
);

-- ─── GRADE 9 · BAND 2 (7 questions) ─────────────────────────────────────────

-- cw_g9b2_01 — Why Soviet Union collapsed
INSERT INTO public.questions (content, answer_format, answer_type, metadata, type, difficulty, question_type, is_active, learning_objective, target_grade, difficulty_band) VALUES (
  '{"question":"Hvad var den vigtigste årsag til Sovjet-Unionens sammenbrud i 1991?","options":["Kombination af stagneret planøkonomi, tabte proxy-krige (Afghanistan), og folkeoprør i Østeuropa der udtømte systemet","Et militært nederlag til USA i en direkte krig","En naturkatastrofe der ødelagde Sovjet-Unionens infrastruktur","FN-sanktioner der afskærede Sovjet fra verdenshandelen"],"correct":"Kombination af stagneret planøkonomi, tabte proxy-krige (Afghanistan), og folkeoprør i Østeuropa der udtømte systemet","accepted_answers":["Kombination af stagneret planøkonomi, tabte proxy-krige (Afghanistan), og folkeoprør i Østeuropa der udtømte systemet"],"review_text":"Sovjet kollapsede ikke fordi USA vandt en krig — det kollapsede indefra. En ineffektiv planøkonomi, den katastrofale Afghanistandkrig og folkeopstande i Østeuropa udtømte systemet. Gorbatjovs reformer forsøgte at redde det — men løsnede kontrollen i stedet."}'::jsonb,
  'mc','short','{"concepts":["Sovjet-sammenbrud","planøkonomi","Afghanistan","folkeopstande"],"misconception_type":"causal_inversion","cognitive_skill":"comprehension","difficulty_type":"conceptual","insight_type":"reframing","challenge_role":"reinforcement","domain":"cold_war"}'::jsonb,
  'mc_single',2,'auto',true,'cold_war',9,2
);

-- cw_g9b2_02 — Why Cuba became flashpoint
INSERT INTO public.questions (content, answer_format, answer_type, metadata, type, difficulty, question_type, is_active, learning_objective, target_grade, difficulty_band) VALUES (
  '{"question":"Hvad var den strategiske grund til at Cuba var så central i Den Kolde Krig?","options":["Cuba ligger 145 km fra Florida — Sovjet-kontrol over Cuba betød at atomraketter kunne placeres direkte på USA''s dørtærskel","Cuba var den eneste kommunistiske stat i hele verden uden for Østeuropa og Kina","Cuba havde de største oliereserver i Vestindien som begge supermagter ønskede at kontrollere","Cuba var symbolsk vigtig for FN som det eneste kommunistiske land i Amerika"],"correct":"Cuba ligger 145 km fra Florida — Sovjet-kontrol over Cuba betød at atomraketter kunne placeres direkte på USA''s dørtærskel","accepted_answers":["Cuba ligger 145 km fra Florida — Sovjet-kontrol over Cuba betød at atomraketter kunne placeres direkte på USA''s dørtærskel"],"review_text":"Geografien var afgørende. Cuba er 145 km fra USA-kysten. Sovjet-raketter der kunne nå Washington D.C. på 14 minutter. For USA var det som en pistol rettet mod tindingen. Cuba-krisen handlede ikke om Cuba — det handlede om magtbalancen på USAs eget baghave."}'::jsonb,
  'mc','short','{"concepts":["Cuba","geografi","strategisk placering","magtbalance"],"misconception_type":"scope_confusion","cognitive_skill":"comprehension","difficulty_type":"conceptual","insight_type":"reframing","challenge_role":"reinforcement","domain":"cold_war"}'::jsonb,
  'mc_single',2,'auto',true,'cold_war',9,2
);

-- cw_g9b2_03 — CIA vs KGB espionage
INSERT INTO public.questions (content, answer_format, answer_type, metadata, type, difficulty, question_type, is_active, learning_objective, target_grade, difficulty_band) VALUES (
  '{"question":"Hvad var CIA og KGBs primære funktion under Den Kolde Krig?","options":["Indsamle information om den anden side — rekruttere spioner, stjæle militære hemmeligheder og manipulere fremmede regeringer","Rekruttere soldater til proxy-krige i Asien og Afrika","Overvåge atomvåbnenes tilstand og forhindre utilsigtet detonation","CIA og KGB samarbejdede hemmelig om at fordele spionopgaverne globalt"],"correct":"Indsamle information om den anden side — rekruttere spioner, stjæle militære hemmeligheder og manipulere fremmede regeringer","accepted_answers":["Indsamle information om den anden side — rekruttere spioner, stjæle militære hemmeligheder og manipulere fremmede regeringer"],"review_text":"CIA og KGB var hinandens modstykker i en skyggeverdenen. De rekrutterede dobbelt-agenter, stjal atomhemmeligheder og forsøgte at destabilisere hinandens allierede. Spionage var en central del af Den Kolde Krig — information var ligeså vigtig som atomvåben."}'::jsonb,
  'mc','short','{"concepts":["CIA","KGB","spionage","informationskrig"],"misconception_type":"false_equivalence","cognitive_skill":"comprehension","difficulty_type":"conceptual","insight_type":"reframing","challenge_role":"reinforcement","domain":"cold_war"}'::jsonb,
  'mc_single',2,'auto',true,'cold_war',9,2
);

-- cw_g9b2_04 — Korean War as proxy
INSERT INTO public.questions (content, answer_format, answer_type, metadata, type, difficulty, question_type, is_active, learning_objective, target_grade, difficulty_band) VALUES (
  '{"question":"Hvad viser Koreakrigen (1950-53) om Den Kolde Krigs natur?","options":["At Den Kolde Krig ikke var kold for dem der faktisk kæmpede — proxy-krige kostede millioner af liv uden at supermangterne formelt kæmpede mod hinanden","At USA og Sovjet samarbejdede om at mægle freden i Korea via FN","At Kina var den egentlige supermagt der styrede den asiatiske del af koldkrigs-konflikterne","At Den Kolde Krig forblev fredelig fordi FN greb hurtigt ind og forhindrede eskalation"],"correct":"At Den Kolde Krig ikke var kold for dem der faktisk kæmpede — proxy-krige kostede millioner af liv uden at supermangterne formelt kæmpede mod hinanden","accepted_answers":["At Den Kolde Krig ikke var kold for dem der faktisk kæmpede — proxy-krige kostede millioner af liv uden at supermangterne formelt kæmpede mod hinanden"],"review_text":"I Koreakrigen døde over 3 millioner — soldater og civile. USA støttede syd, Kina og Sovjet støttede nord. Krigen var kold for supermangterne. Varm og dødelig for koreanerne. Kold Krig er et vestcentreret udtryk der skjuler de mange proxy-krigers realitet."}'::jsonb,
  'mc','short','{"concepts":["Koreakrig","proxy-krig","tab","misconception-fredelig-koldkrig"],"misconception_type":"overgeneralization","cognitive_skill":"comprehension","difficulty_type":"conceptual","insight_type":"perspective_shift","challenge_role":"reinforcement","domain":"cold_war"}'::jsonb,
  'mc_single',2,'auto',true,'cold_war',9,2
);

-- cw_g9b2_05 — Vietnam lessons
INSERT INTO public.questions (content, answer_format, answer_type, metadata, type, difficulty, question_type, is_active, learning_objective, target_grade, difficulty_band) VALUES (
  '{"question":"Hvad er den vigtigste lektie fra USA-engagementet i Vietnamkrigen?","options":["Militær overlegenhed garanterer ikke succes mod en modstandsbevægelse med stærk folkelig opbakning og ideologisk motivation","At Sovjet-støtten til Nordvietnam var den direkte årsag til USAs nederlag","At USA tabte fordi det aldrig brugte sin fulde militære kapacitet inklusive atomvåben","At atomvåben var den eneste effektive løsning men politikerne undlod at bruge dem"],"correct":"Militær overlegenhed garanterer ikke succes mod en modstandsbevægelse med stærk folkelig opbakning og ideologisk motivation","accepted_answers":["Militær overlegenhed garanterer ikke succes mod en modstandsbevægelse med stærk folkelig opbakning og ideologisk motivation"],"review_text":"USA var militært langt stærkere end Nordvietnam og tabte alligevel. Nordvietnameserne kæmpede for national befrielse — det var svært at bekæmpe med fly og bombefly. Vietnamkrigen viser at teknologisk og militær overlegenhed ikke erstatter folkelig sammenhæng."}'::jsonb,
  'mc','short','{"concepts":["Vietnamkrig","militær overlegenhed","folkelig opbakning","proxy-krig"],"misconception_type":"false_equivalence","cognitive_skill":"comprehension","difficulty_type":"conceptual","insight_type":"reframing","challenge_role":"reinforcement","domain":"cold_war"}'::jsonb,
  'mc_single',2,'auto',true,'cold_war',9,2
);

-- cw_g9b2_06 — Moon landing significance
INSERT INTO public.questions (content, answer_format, answer_type, metadata, type, difficulty, question_type, is_active, learning_objective, target_grade, difficulty_band) VALUES (
  '{"question":"Hvad betød USA''s månelanding i 1969 for Den Kolde Krigs ideologiske kamp?","options":["Det var en symbolsk sejr der demonstrerede at det demokratiske kapitalistiske system kunne mobilisere ressourcer og innovation og dermed vinde den ideologiske kamp","Det betød at USA nu teknisk set kunne placere atomvåben på Månen til trussel mod Sovjet","Det afsluttede rumkapløbet — begge sider indstillede derefter rumforskning","Det beviste at Sovjet-videnskab var underlegen i alle discipliner og alt teknologisk arbejde"],"correct":"Det var en symbolsk sejr der demonstrerede at det demokratiske kapitalistiske system kunne mobilisere ressourcer og innovation og dermed vinde den ideologiske kamp","accepted_answers":["Det var en symbolsk sejr der demonstrerede at det demokratiske kapitalistiske system kunne mobilisere ressourcer og innovation og dermed vinde den ideologiske kamp"],"review_text":"Neil Armstrongs skridt på Månen i 1969 var ikke blot teknologi — det var ideologisk budskab: frihed og kapitalisme kan opnå det umulige. Milliarder så det i TV. Sovjet nåede aldrig Månen. Som propaganda-sejr var det enorm."}'::jsonb,
  'mc','short','{"concepts":["månelanding","rumkapløb","ideologisk sejr","kapitalisme vs kommunisme"],"misconception_type":"scope_confusion","cognitive_skill":"comprehension","difficulty_type":"conceptual","insight_type":"reframing","challenge_role":"reinforcement","domain":"cold_war"}'::jsonb,
  'mc_single',2,'auto',true,'cold_war',9,2
);

-- cw_g9b2_07 — Radio Free Europe / information war
INSERT INTO public.questions (content, answer_format, answer_type, metadata, type, difficulty, question_type, is_active, learning_objective, target_grade, difficulty_band) VALUES (
  '{"question":"Hvad var Radio Free Europe og Voice of Americas rolle under Den Kolde Krig?","options":["De transmitterede vestlige nyheder og information til borgere i Østeuropa der ellers ikke havde adgang til frie medier — informationskrig via radiobølger","Stationerne programmerede primært musik uden politisk indhold for at fremme kulturel forståelse","De var primært rettet mod Sovjet-militær for at desinformere officererne","Radio Free Europe var et FN-initiativ for neutral kulturel udveksling"],"correct":"De transmitterede vestlige nyheder og information til borgere i Østeuropa der ellers ikke havde adgang til frie medier — informationskrig via radiobølger","accepted_answers":["De transmitterede vestlige nyheder og information til borgere i Østeuropa der ellers ikke havde adgang til frie medier — informationskrig via radiobølger"],"review_text":"Bag Jerntæppet var vestlige nyheder forbudte og statsmedierne kontrollerede alt. Radio Free Europe sendte nyheder og politisk analyse til millioner af østeuropæere. Østblokregeringerne jammede signalerne — men folk lyttede alligevel. Information var et våben."}'::jsonb,
  'mc','short','{"concepts":["Radio Free Europe","informationskrig","censur","Østeuropa","propaganda"],"misconception_type":"scope_confusion","cognitive_skill":"comprehension","difficulty_type":"conceptual","insight_type":"reframing","challenge_role":"reinforcement","domain":"cold_war"}'::jsonb,
  'mc_single',2,'auto',true,'cold_war',9,2
);

-- ─── GRADE 9 · BAND 3 (7 questions) ─────────────────────────────────────────

-- cw_g9b3_01 — Cuba crisis consequences (hotline)
INSERT INTO public.questions (content, answer_format, answer_type, metadata, type, difficulty, question_type, is_active, learning_objective, target_grade, difficulty_band) VALUES (
  '{"question":"Hvad var Cuba-krisens vigtigste konsekvens for hele verden efter at den var overstået?","options":["Bevidstheden om at atomkrig var muligt førte til den direkte hotline mellem Washington og Moskva — for at forhindre at en misforståelse udløste atomkrig","Cuba kom under permanent amerikansk militær kontrol som del af forliget","Sovjet gav afkald på alle sine atomvåben som betingelse for USA''s tilbagetrækning","FN overtog forvaltningen af alle fremtidige koldkrigs-konflikter"],"correct":"Bevidstheden om at atomkrig var muligt førte til den direkte hotline mellem Washington og Moskva — for at forhindre at en misforståelse udløste atomkrig","accepted_answers":["Bevidstheden om at atomkrig var muligt førte til den direkte hotline mellem Washington og Moskva — for at forhindre at en misforståelse udløste atomkrig"],"review_text":"Cuba-krisen lærte verden hvad det betød at stå på randen. Resultatet: en direkte hotline fra Washington til Moskva blev oprettet i 1963. Ingen ønskede at en teknisk fejl eller misforståelse skulle starte en atomkrig. Krisen skabte paradoksalt en marginalt sikrere verden."}'::jsonb,
  'mc','short','{"concepts":["Cuba-krisen","hotline","konsekvenser","atomkrig-forebyggelse","misconception-kun-Cuba"],"misconception_type":"scope_confusion","cognitive_skill":"analysis","difficulty_type":"analytical","insight_type":"reframing","challenge_role":"challenge","domain":"cold_war"}'::jsonb,
  'mc_single',3,'auto',true,'cold_war',9,3
);

-- cw_g9b3_02 — Communism theory vs practice
INSERT INTO public.questions (content, answer_format, answer_type, metadata, type, difficulty, question_type, is_active, learning_objective, target_grade, difficulty_band) VALUES (
  '{"question":"Hvad er forskellen på Karl Marx'' kommunistiske teori og den kommunisme Sovjet implementerede?","options":["Marx forestillede sig fælles ejerskab som befrielse af arbejderne — Sovjet-kommunisme blev et enpartidiktatur med statsejerskab og politisk undertrykkelse","De to var identiske — Marx designede specifikt Sovjet-systemet og Lenin fulgte planen nøje","Sovjet-kommunisme var faktisk tættere på kapitalisme end på Marx'' teori fordi staten ejede markedet","Marx ville ikke have anerkendt Sovjet som kommunistisk — men begge systemer var i princippet diktaturer"],"correct":"Marx forestillede sig fælles ejerskab som befrielse af arbejderne — Sovjet-kommunisme blev et enpartidiktatur med statsejerskab og politisk undertrykkelse","accepted_answers":["Marx forestillede sig fælles ejerskab som befrielse af arbejderne — Sovjet-kommunisme blev et enpartidiktatur med statsejerskab og politisk undertrykkelse"],"review_text":"Marx forestillede sig kommunisme som befrielse fra kapitalistisk udbytning — ikke diktatur og hemmelig politi. Lenin og Stalin formede teorien til noget vidt forskelligt. Ideologi og implementering kan divergere dramatisk. Det er en af historiens vigtigste lektioner."}'::jsonb,
  'mc','short','{"concepts":["Marx","kommunisme","Sovjet","teori vs praksis","misconception-kommunisme=diktatur"],"misconception_type":"false_equivalence","cognitive_skill":"analysis","difficulty_type":"analytical","insight_type":"reframing","challenge_role":"challenge","domain":"cold_war"}'::jsonb,
  'mc_single',3,'auto',true,'cold_war',9,3
);

-- cw_g9b3_03 — Cold War and culture
INSERT INTO public.questions (content, answer_format, answer_type, metadata, type, difficulty, question_type, is_active, learning_objective, target_grade, difficulty_band) VALUES (
  '{"question":"Hvad viser Den Kolde Krigs påvirkning på film, musik og litteratur?","options":["At konflikten ikke var begrænset til militær og politik — den formede hele kulturen med temaer om frygt, spionage, teknologisk fremtid og menneskelig frihed","At kun statssponsoreret propaganda-kunst var påvirket — al anden kultur var fri for politisk indflydelse","At Sovjet-kulturen var stærkt ideologisk påvirket men vestlig kultur forblev helt fri","At Den Kolde Krig knapt påvirkede kulturen — folk ignorerede i stor stil konflikten i hverdagen"],"correct":"At konflikten ikke var begrænset til militær og politik — den formede hele kulturen med temaer om frygt, spionage, teknologisk fremtid og menneskelig frihed","accepted_answers":["At konflikten ikke var begrænset til militær og politik — den formede hele kulturen med temaer om frygt, spionage, teknologisk fremtid og menneskelig frihed"],"review_text":"James Bond-film, Orwells 1984, Stanley Kubricks Dr. Strangelove, og rockmusikkens frigørelsesbudskab — alle formet af og reaktioner på Den Kolde Krig. Frygten for atomkrig og dobbelt-agenter prægede populærkulturen i årtier. Kulturen er historiens spejl."}'::jsonb,
  'mc','short','{"concepts":["kultur","film","litteratur","Kolde Krig","frygt"],"misconception_type":"scope_confusion","cognitive_skill":"analysis","difficulty_type":"analytical","insight_type":"reframing","challenge_role":"challenge","domain":"cold_war"}'::jsonb,
  'mc_single',3,'auto',true,'cold_war',9,3
);

-- cw_g9b3_04 — Nuclear deterrence: prevent or displace war?
INSERT INTO public.questions (content, answer_format, answer_type, metadata, type, difficulty, question_type, is_active, learning_objective, target_grade, difficulty_band) VALUES (
  '{"question":"En historiker hævder at atomvåben forhindrede krig under Den Kolde Krig. Hvad er den vigtigste indvending?","options":["Atomvåben forhindrede direkte krig MELLEM supermangterne — men proxy-krige der dræbte millioner fortsatte. Forhindret krig er et vestcentreret perspektiv","Påstanden er fuldstændig korrekt — ingen krige skete nogen steder i verden efter 1945","Atomvåben forhindrede slet ingen krige — konflikter fortsatte nøjagtig som de altid ville have gjort","Indvendingen er at atomvåben aldrig var en reel trussel og dermed ikke påvirkede noget"],"correct":"Atomvåben forhindrede direkte krig MELLEM supermangterne — men proxy-krige der dræbte millioner fortsatte. Forhindret krig er et vestcentreret perspektiv","accepted_answers":["Atomvåben forhindrede direkte krig MELLEM supermangterne — men proxy-krige der dræbte millioner fortsatte. Forhindret krig er et vestcentreret perspektiv"],"review_text":"MAD forhindrede USA og Sovjet i at angribe hinanden direkte. Men det skiftede krigen til proxy-konflikter: Korea, Vietnam, Angola, Afghanistan. Millioner af mennesker døde. Fra supermangts-perspektiv var det fred. Fra koreansk eller vietnamesisk perspektiv var det krig. Perspektiv afgør konklusionen."}'::jsonb,
  'mc','short','{"concepts":["atomafskrækkelse","proxy-krig","perspektiv","misconception-atomvåben-forhindrer-krig"],"misconception_type":"scope_confusion","cognitive_skill":"analysis","difficulty_type":"analytical","insight_type":"perspective_shift","challenge_role":"challenge","domain":"cold_war"}'::jsonb,
  'mc_single',3,'auto',true,'cold_war',9,3
);

-- cw_g9b3_05 — Germany division and identity
INSERT INTO public.questions (content, answer_format, answer_type, metadata, type, difficulty, question_type, is_active, learning_objective, target_grade, difficulty_band) VALUES (
  '{"question":"Hvad var den dybeste konsekvens af Tysklands deling i Øst og Vest for det tyske folk?","options":["To generationer voksede op i radikalt verschiedene politiske virkeligheder — og genforeningen i 1990 skabte ny kompleksitet da to fundamentalt different befolkninger mødtes","Delingen var primært symbolsk — begge tysklande fungerede i praksis identisk","Østtyskerne ønskede ikke genforening da de var godt tilfredse med kommunismen","Den tyske deling var planlagt som en midlertidig løsning der varede 2-3 år"],"correct":"To generationer voksede op i radikalt verschiedene politiske virkeligheder — og genforeningen i 1990 skabte ny kompleksitet da to fundamentalt different befolkninger mødtes","accepted_answers":["To generationer voksede op i radikalt verschiedene politiske virkeligheder — og genforeningen i 1990 skabte ny kompleksitet da to fundamentalt different befolkninger mødtes"],"review_text":"I vest: demokrati, velstand og rejsefrihed. I øst: enpartidiktatur, planøkonomi og Stasi-overvågning. Da Muren faldt og genforeningen kom, mødte to meget forskellige befolkninger hinanden. Ossi og Wessi stereotyper vidnede om de dybe skel der stadig eksisterer."}'::jsonb,
  'mc','short','{"concepts":["Tysklands deling","national identitet","genforening","Ossi Wessi"],"misconception_type":"overgeneralization","cognitive_skill":"analysis","difficulty_type":"analytical","insight_type":"perspective_shift","challenge_role":"challenge","domain":"cold_war"}'::jsonb,
  'mc_single',3,'auto',true,'cold_war',9,3
);

-- cw_g9b3_06 — End of Cold War not instant (misconception)
INSERT INTO public.questions (content, answer_format, answer_type, metadata, type, difficulty, question_type, is_active, learning_objective, target_grade, difficulty_band) VALUES (
  '{"question":"Hvad er forkert ved forestillingen om at Den Kolde Krig pludselig sluttede da Berlinmuren faldt?","options":["Murens fald var dramatisk synligt — men årsagerne byggede sig op over årtier: Sovjet-økonomisvigt, Gorbatjovs reformer og folkeopstande i Østeuropa","Forestillingen er korrekt — Murens fald var den direkte og øjeblikkelige årsag til Den Kolde Krigs pludselige ophør","Muren faldt faktisk ikke spontant — det var et planlagt politisk arrangement","Berlinmuren faldt i 1985 under Reagan-Gorbatjov-topmødet — ikke i 1989"],"correct":"Murens fald var dramatisk synligt — men årsagerne byggede sig op over årtier: Sovjet-økonomisvigt, Gorbatjovs reformer og folkeopstande i Østeuropa","accepted_answers":["Murens fald var dramatisk synligt — men årsagerne byggede sig op over årtier: Sovjet-økonomisvigt, Gorbatjovs reformer og folkeopstande i Østeuropa"],"review_text":"Berlinmurens fald 9. november 1989 var dramatisk men ikke pludseligt. Sovjet-Unionens økonomi brød ned efter årtier. Katastrofekrigen i Afghanistan udtømte ressourcerne. Gorbatjovs reformer løsnede kontrollen. Folkeopstande fejede kommunistregimer i Polen og Ungarn. Muren var et effekt — ikke en årsag."}'::jsonb,
  'mc','short','{"concepts":["Kolde Krig afslutning","Berlinmur","Gorbatjov","misconception-øjeblikkelig slutning","kausalitet"],"misconception_type":"causal_inversion","cognitive_skill":"analysis","difficulty_type":"analytical","insight_type":"reframing","challenge_role":"challenge","domain":"cold_war"}'::jsonb,
  'mc_single',3,'auto',true,'cold_war',9,3
);

-- cw_g9b3_07 — Arms race economic costs on Soviet
INSERT INTO public.questions (content, answer_format, answer_type, metadata, type, difficulty, question_type, is_active, learning_objective, target_grade, difficulty_band) VALUES (
  '{"question":"Hvad var atomkapløbets langsigtede konsekvens for Sovjet-Unionens økonomi?","options":["Atomkapløbet krævede en uforholdsmæssig andel af Sovjet-Unionens ressourcer som planøkonomien ikke kunne bære — og bidrog direkte til det endelige sammenbrud","Atomkapløbet var faktisk godt for Sovjet-Unionens økonomi fordi det skabte industriel vækst og eksportindtægter","USA brugte langt mere på atomvåben end Sovjet og det forklarede Sovjet-Unionens relative styrke","Atomkapløbet kostede begge lande nøjagtigt det samme i relative termer og favoriserede ingen"],"correct":"Atomkapløbet krævede en uforholdsmæssig andel af Sovjet-Unionens ressourcer som planøkonomien ikke kunne bære — og bidrog direkte til det endelige sammenbrud","accepted_answers":["Atomkapløbet krævede en uforholdsmæssig andel af Sovjet-Unionens ressourcer som planøkonomien ikke kunne bære — og bidrog direkte til det endelige sammenbrud"],"review_text":"Sovjet brugte en langt højere andel af sit BNP på militær end USA. En planøkonomi der prioriterede raketter over forbrugsgoder skabte mangler og utilfredshed. Atomkapløbet var ikke kun en sikkerhedsrisiko — det var en langsigtet dødsstraf for den sovjet-kommunistiske økonomi."}'::jsonb,
  'mc','short','{"concepts":["atomkapløb","Sovjet-økonomi","planøkonomi","Sovjet-sammenbrud","ressourcer"],"misconception_type":"causal_inversion","cognitive_skill":"analysis","difficulty_type":"analytical","insight_type":"reframing","challenge_role":"challenge","domain":"cold_war"}'::jsonb,
  'mc_single',3,'auto',true,'cold_war',9,3
);

-- ─── GRADE 9 · BAND 4 (5 questions) ─────────────────────────────────────────

-- cw_g9b4_01 — Moral complexity: neither side was right (misconception)
INSERT INTO public.questions (content, answer_format, answer_type, metadata, type, difficulty, question_type, is_active, learning_objective, target_grade, difficulty_band) VALUES (
  '{"question":"Hvad er det mest historisk præcise svar på spørgsmålet om hvem der var den gode side i Den Kolde Krig?","options":["Ingen side var entydigt god — USA støttede diktaturer i Latinamerika og Asien; Sovjet undertrykte befolkninger og invaderede Ungarn og Tjekkoslovakiet. Begge retfærdiggjorde det ideologisk","USA var entydigt den gode side fordi det forsvarede demokrati og menneskeret globalt","Sovjet var den gode side fordi det forsvarede lighed og arbejdernes rettigheder mod kapitalisme","Det er et meningsløst spørgsmål — begge sider var identisk onde og bør ikke sammenlignes"],"correct":"Ingen side var entydigt god — USA støttede diktaturer i Latinamerika og Asien; Sovjet undertrykte befolkninger og invaderede Ungarn og Tjekkoslovakiet. Begge retfærdiggjorde det ideologisk","accepted_answers":["Ingen side var entydigt god — USA støttede diktaturer i Latinamerika og Asien; Sovjet undertrykte befolkninger og invaderede Ungarn og Tjekkoslovakiet. Begge retfærdiggjorde det ideologisk"],"review_text":"USA støttede korrupte diktatorer i Latinamerika og Asien når de var anti-kommunistiske. Sovjet knuste folkeopstande i Ungarn (1956) og Tjekkoslovakiet (1968). Begge parter brugte ideologi til at retfærdiggøre magtpolitik. En historiker stiller spørgsmål og holder begge sider ansvarlige."}'::jsonb,
  'mc','short','{"concepts":["moralsk kompleksitet","USA","Sovjet","misconception-USA-altid-rigtig","misconception-Sovjet-altid-rigtig"],"misconception_type":"false_equivalence","cognitive_skill":"evaluation","difficulty_type":"applied","insight_type":"perspective_shift","challenge_role":"deep_challenge","domain":"cold_war"}'::jsonb,
  'mc_single',4,'auto',true,'cold_war',9,4
);

-- cw_g9b4_02 — Could the Cold War have been avoided?
INSERT INTO public.questions (content, answer_format, answer_type, metadata, type, difficulty, question_type, is_active, learning_objective, target_grade, difficulty_band) VALUES (
  '{"question":"Var Den Kolde Krig uundgåelig efter 2. Verdenskrig — eller kunne den have været forhindret?","options":["Historikere er uenige: strukturalister siger modsatrettede interesser var uundgåelige; revisionister siger fejltagelser og misforståelser fra begge sider eskalerede konflikten unødigt","Den var helt uundgåelig — ideologiske modsætninger kræver altid krig og konfrontation","Den var fuldt undgåelig — Roosevelt og Stalin ville have fundet en fredsaftale hvis Roosevelt ikke var død","Den var uundgåelig alene fordi atombombens eksistens automatisk skaber konflikt"],"correct":"Historikere er uenige: strukturalister siger modsatrettede interesser var uundgåelige; revisionister siger fejltagelser og misforståelser fra begge sider eskalerede konflikten unødigt","accepted_answers":["Historikere er uenige: strukturalister siger modsatrettede interesser var uundgåelige; revisionister siger fejltagelser og misforståelser fra begge sider eskalerede konflikten unødigt"],"review_text":"Traditionalisterne siger Sovjet-ekspansion tvang USA til at reagere. Revisionisterne siger USA provokerede ved at omringe Sovjet og bruge atombombe-diplomati. Post-revisionisterne siger begge sider misforstod hinanden. Historien rummer ikke ét svar — men det er ikke det samme som at alle svar er lige gyldige."}'::jsonb,
  'mc','short','{"concepts":["Kolde Krig-oprindelse","historisk debat","uundgåelighed","strukturalisme","revisionisme"],"misconception_type":"causal_inversion","cognitive_skill":"evaluation","difficulty_type":"applied","insight_type":"perspective_shift","challenge_role":"deep_challenge","domain":"cold_war"}'::jsonb,
  'mc_single',4,'auto',true,'cold_war',9,4
);

-- cw_g9b4_03 — How propaganda shaped both populations symmetrically
INSERT INTO public.questions (content, answer_format, answer_type, metadata, type, difficulty, question_type, is_active, learning_objective, target_grade, difficulty_band) VALUES (
  '{"question":"Hvad var den dybeste lighed mellem USA-propaganda og Sovjet-propaganda under Den Kolde Krig?","options":["Begge skabte et forenklet verdensbillede — vi er de gode, de er de onde — og formede dermed hvad millioner af borgere troede var virkelighed","Begge brugte præcis de samme teknikker og medier til at sprede sit budskab til befolkningerne","USA-propaganda var faktuelt korrekt; Sovjet-propaganda var rent løgn — det var den vigtigste forskel","Begge lande afholdt sig fra at bruge propaganda mod egne borgere — kun mod den fjendtlige befolkning"],"correct":"Begge skabte et forenklet verdensbillede — vi er de gode, de er de onde — og formede dermed hvad millioner af borgere troede var virkelighed","accepted_answers":["Begge skabte et forenklet verdensbillede — vi er de gode, de er de onde — og formede dermed hvad millioner af borgere troede var virkelighed"],"review_text":"To-sidigt fjendbillede er effektiv propaganda. Begge systemer forenklede virkeligheden til os og dem. Det skabte befolkninger der var villige til at acceptere ofringer for at bekæmpe den onde fjende. Det gælder begge sider. Det er det mest foruroligende aspekt af propagandaens effektivitet."}'::jsonb,
  'mc','short','{"concepts":["propaganda","symmetri","befolkningskontrol","fjendbillede","begge sider"],"misconception_type":"false_equivalence","cognitive_skill":"evaluation","difficulty_type":"applied","insight_type":"perspective_shift","challenge_role":"deep_challenge","domain":"cold_war"}'::jsonb,
  'mc_single',4,'auto',true,'cold_war',9,4
);

-- cw_g9b4_04 — Legacy of the Cold War today
INSERT INTO public.questions (content, answer_format, answer_type, metadata, type, difficulty, question_type, is_active, learning_objective, target_grade, difficulty_band) VALUES (
  '{"question":"Hvad er Den Kolde Krigs vigtigste arv i verden i dag?","options":["Geopolitiske spændinger, kernevåbenprogrammer og alliancemønstre der alle direkte stammer fra Den Kolde Krig — inklusive NATO og delte nationer som Korea","Den Kolde Krig efterlod ingen varige spor — verden startede reelt på en blank side i 1991","Den primære arv er rumforskning og teknologi som GPS og internet — ikke politiske strukturer","Arven er primært kulturel — film og litteratur — men ingen politiske strukturer overlevede 1991"],"correct":"Geopolitiske spændinger, kernevåbenprogrammer og alliancemønstre der alle direkte stammer fra Den Kolde Krig — inklusive NATO og delte nationer som Korea","accepted_answers":["Geopolitiske spændinger, kernevåbenprogrammer og alliancemønstre der alle direkte stammer fra Den Kolde Krig — inklusive NATO og delte nationer som Korea"],"review_text":"NATO eksisterer. Nordkorea er stadig delt fra syd. Rusland og Vesten er stadig dybt mistroiske. Atomprogrammer eksisterer i mange lande. Den Kolde Krigs strukturer er ikke forsvundet — de er transformeret. 1991 var ikke et nyt kapitel; det var et afsnitsslut midt i en fortsat fortælling."}'::jsonb,
  'mc','short','{"concepts":["Kolde Krig arv","NATO","Korea","nutidig relevans","geopolitik"],"misconception_type":"temporal_confusion","cognitive_skill":"evaluation","difficulty_type":"applied","insight_type":"perspective_shift","challenge_role":"deep_challenge","domain":"cold_war"}'::jsonb,
  'mc_single',4,'auto',true,'cold_war',9,4
);

-- cw_g9b4_05 — Nuclear deterrence paradox (deepest synthesis)
INSERT INTO public.questions (content, answer_format, answer_type, metadata, type, difficulty, question_type, is_active, learning_objective, target_grade, difficulty_band) VALUES (
  '{"question":"Hvad er det dybeste paradoks ved nuklear afskrækkelse som strategisk doktrin?","options":["Systemets effektivitet kræver at begge sider TROEDE på at den anden ville bruge atomvåben — men brugte de dem ville det betyde civilisationens undergang. Stabilitet baseret på troværdig irrationel trussel","Paradokset er at nuklear afskrækkelse er det eneste forsvarssystem der aldrig virker i praksis","Paradokset er at jo flere atomvåben man ejede desto svagere var man militært set","Der er intet paradoks — nuklear afskrækkelse er en rationel og simpel strategisk doktrin"],"correct":"Systemets effektivitet kræver at begge sider TROEDE på at den anden ville bruge atomvåben — men brugte de dem ville det betyde civilisationens undergang. Stabilitet baseret på troværdig irrationel trussel","accepted_answers":["Systemets effektivitet kræver at begge sider TROEDE på at den anden ville bruge atomvåben — men brugte de dem ville det betyde civilisationens undergang. Stabilitet baseret på troværdig irrationel trussel"],"review_text":"MAD kræver at truslen er troværdig: du skal overbevise fjenden om at du faktisk vil udslette jer begge. Men ingen rationel leder ville gøre det. Paradokset: rationelle ledere ville aldrig bruge atomvåben — og det er præcis det der gør truslen troværdig, fordi fjenden tror du måske er irrationel. En fascinerende og skræmmende logik."}'::jsonb,
  'mc','short','{"concepts":["nuklear afskrækkelse","MAD","paradoks","rationalitet","irrationel trussel"],"misconception_type":"false_equivalence","cognitive_skill":"evaluation","difficulty_type":"applied","insight_type":"perspective_shift","challenge_role":"deep_challenge","domain":"cold_war"}'::jsonb,
  'mc_single',4,'auto',true,'cold_war',9,4
);
